// src/components/Ganancias/EstadisticasVentas.js
import React, { useState, useEffect } from 'react';
import {
    Box, Typography, Paper, Table, TableBody, TableCell,
    TableContainer, TableHead, TableRow, Button,
    Chip, Avatar, IconButton, ToggleButton,
    ToggleButtonGroup, MenuItem, Select, FormControl,
    InputLabel, Stack, Divider, Drawer, useMediaQuery, useTheme
} from '@mui/material';
import { ref, get } from "firebase/database";
import { db } from "./firebaseConfig";
import TrendingUpIcon from '@mui/icons-material/TrendingUp';
import EmojiEventsIcon from '@mui/icons-material/EmojiEvents';
import PersonIcon from '@mui/icons-material/Person';
import CloseIcon from '@mui/icons-material/Close';
import BarChartIcon from '@mui/icons-material/BarChart';
import StarIcon from '@mui/icons-material/Star';
import FilterListIcon from '@mui/icons-material/FilterList';

const EstadisticasVentas = () => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const [open, setOpen] = useState(false);
    const [ventas, setVentas] = useState([]);
    const [productosVendidos, setProductosVendidos] = useState([]);
    const [mejoresClientes, setMejoresClientes] = useState([]);
    const [periodo, setPeriodo] = useState('todos');
    const [mesSeleccionado, setMesSeleccionado] = useState(new Date().getMonth());
    const [añoSeleccionado, setAñoSeleccionado] = useState(new Date().getFullYear());
    const [loading, setLoading] = useState(false);
    const [mostrarFiltros, setMostrarFiltros] = useState(false);

    useEffect(() => {
        if (open) {
            cargarDatos();
            // Bloquear scroll del body cuando el drawer está abierto
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = 'unset';
        }

        return () => {
            document.body.style.overflow = 'unset';
        };
    }, [open, periodo, mesSeleccionado, añoSeleccionado]);

    const cargarDatos = async () => {
        setLoading(true);
        try {
            const ventasRef = ref(db, "ventas");
            const snapshot = await get(ventasRef);

            if (snapshot.exists()) {
                const data = snapshot.val();
                let ventasList = Object.values(data);
                ventasList = filtrarPorPeriodo(ventasList);
                setVentas(ventasList);
                calcularEstadisticas(ventasList);
            }
        } catch (error) {
            console.error("Error al cargar ventas:", error);
        } finally {
            setLoading(false);
        }
    };

    const filtrarPorPeriodo = (ventasList) => {
        switch (periodo) {
            case 'mes':
                return ventasList.filter(v => {
                    const fecha = new Date(v.fecha);
                    return fecha.getMonth() === mesSeleccionado &&
                        fecha.getFullYear() === añoSeleccionado;
                });
            case 'año':
                return ventasList.filter(v => {
                    const fecha = new Date(v.fecha);
                    return fecha.getFullYear() === añoSeleccionado;
                });
            default:
                return ventasList;
        }
    };

    const calcularEstadisticas = (ventasList) => {
        // Calcular productos más vendidos
        const productosMap = new Map();

        ventasList.forEach(venta => {
            if (venta.productos && Array.isArray(venta.productos)) {
                venta.productos.forEach(producto => {
                    const key = producto.id || producto.nombre;
                    if (productosMap.has(key)) {
                        const existing = productosMap.get(key);
                        existing.cantidad += producto.cantidad;
                        existing.ventas += producto.cantidad * producto.precioVenta;
                        existing.ganancia += producto.ganancia || ((producto.precioVenta - producto.precioCosto) * producto.cantidad);
                    } else {
                        productosMap.set(key, {
                            id: key,
                            nombre: producto.nombre,
                            cantidad: producto.cantidad,
                            ventas: producto.cantidad * producto.precioVenta,
                            ganancia: producto.ganancia || ((producto.precioVenta - producto.precioCosto) * producto.cantidad)
                        });
                    }
                });
            }
        });

        const productosOrdenados = Array.from(productosMap.values())
            .sort((a, b) => b.cantidad - a.cantidad);
        setProductosVendidos(productosOrdenados);

        // Calcular mejores clientes
        const clientesMap = new Map();

        ventasList.forEach(venta => {
            const cliente = venta.cliente;
            if (clientesMap.has(cliente)) {
                const existing = clientesMap.get(cliente);
                existing.totalCompras += venta.total;
                existing.gananciaTotal += venta.gananciaTotal;
                existing.cantidadCompras += 1;
                existing.productosComprados += venta.productos?.length || 0;
            } else {
                clientesMap.set(cliente, {
                    nombre: cliente,
                    totalCompras: venta.total || 0,
                    gananciaTotal: venta.gananciaTotal || 0,
                    cantidadCompras: 1,
                    productosComprados: venta.productos?.length || 0,
                    ultimaCompra: venta.fecha
                });
            }
        });

        const clientesOrdenados = Array.from(clientesMap.values())
            .sort((a, b) => b.totalCompras - a.totalCompras);
        setMejoresClientes(clientesOrdenados);
    };

    const obtenerNombreMes = (mes) => {
        const meses = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
            "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
        return meses[mes];
    };

    const meses = Array.from({ length: 12 }, (_, i) => ({ value: i, label: obtenerNombreMes(i) }));
    const años = [2023, 2024, 2025, 2026];

    // Componente de filtros
    const FiltrosContent = () => (
        <Stack spacing={2}>
            <Typography variant="subtitle2">Filtrar por período:</Typography>
            <ToggleButtonGroup
                value={periodo}
                exclusive
                onChange={(e, val) => val && setPeriodo(val)}
                size="small"
                orientation={isMobile ? "vertical" : "horizontal"}
                sx={{ flexWrap: 'wrap' }}
            >
                <ToggleButton value="todos">Todos</ToggleButton>
                <ToggleButton value="mes">Mes</ToggleButton>
                <ToggleButton value="año">Año</ToggleButton>
            </ToggleButtonGroup>

            {periodo === 'mes' && (
                <Stack direction={isMobile ? "column" : "row"} spacing={2}>
                    <FormControl size="small" fullWidth>
                        <InputLabel>Mes</InputLabel>
                        <Select
                            value={mesSeleccionado}
                            onChange={(e) => setMesSeleccionado(e.target.value)}
                            label="Mes"
                        >
                            {meses.map(mes => (
                                <MenuItem key={mes.value} value={mes.value}>{mes.label}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                    <FormControl size="small" fullWidth>
                        <InputLabel>Año</InputLabel>
                        <Select
                            value={añoSeleccionado}
                            onChange={(e) => setAñoSeleccionado(e.target.value)}
                            label="Año"
                        >
                            {años.map(año => (
                                <MenuItem key={año} value={año}>{año}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Stack>
            )}

            {periodo === 'año' && (
                <FormControl size="small" fullWidth>
                    <InputLabel>Año</InputLabel>
                    <Select
                        value={añoSeleccionado}
                        onChange={(e) => setAñoSeleccionado(e.target.value)}
                        label="Año"
                    >
                        {años.map(año => (
                            <MenuItem key={año} value={año}>{año}</MenuItem>
                        ))}
                    </Select>
                </FormControl>
            )}
        </Stack>
    );

    return (
        <>
            {/* Botón para abrir estadísticas */}
            <Button
                variant="contained"
                onClick={() => setOpen(true)}
                sx={{
                    mt: 2,
                    mb: 2,
                    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                    '&:hover': {
                        background: 'linear-gradient(135deg, #5a67d8 0%, #6b46a1 100%)'
                    }
                }}
                startIcon={<BarChartIcon />}
                fullWidth
            >
                📊 Ver Estadísticas de Ventas
            </Button>

            {/* Drawer en lugar de Modal para mejor scroll en móvil */}
            <Drawer
                anchor="bottom"
                open={open}
                onClose={() => setOpen(false)}
                sx={{
                    '& .MuiDrawer-paper': {
                        height: '90vh',
                        maxHeight: '90vh',
                        borderTopLeftRadius: 16,
                        borderTopRightRadius: 16,
                        overflow: 'auto'
                    }
                }}
            >
                <Box sx={{ p: { xs: 2, sm: 3 }, pb: 4 }}>
                    {/* Header */}
                    <Box sx={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        mb: 2,
                        position: 'sticky',
                        top: 0,
                        backgroundColor: 'white',
                        zIndex: 1,
                        pb: 1
                    }}>
                        <Typography variant="h6" sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <BarChartIcon color="primary" />
                            Estadísticas de Ventas
                        </Typography>
                        <IconButton onClick={() => setOpen(false)}>
                            <CloseIcon />
                        </IconButton>
                    </Box>

                    {/* Botón de filtros para móvil */}
                    {isMobile && (
                        <Button
                            fullWidth
                            variant="outlined"
                            onClick={() => setMostrarFiltros(!mostrarFiltros)}
                            startIcon={<FilterListIcon />}
                            sx={{ mb: 2 }}
                            size="small"
                        >
                            {mostrarFiltros ? "Ocultar Filtros" : "Mostrar Filtros"}
                        </Button>
                    )}

                    {/* Filtros */}
                    {(mostrarFiltros || !isMobile) && (
                        <Paper sx={{ p: 2, mb: 3, backgroundColor: '#f5f5f5' }}>
                            <FiltrosContent />
                        </Paper>
                    )}

                    {loading ? (
                        <Typography textAlign="center">Cargando datos...</Typography>
                    ) : (
                        <>
                            {/* Mejores Clientes */}
                            <Typography variant="h6" sx={{ mt: 2, mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
                                <EmojiEventsIcon color="warning" />
                                🏆 Mejores Clientes
                            </Typography>

                            <TableContainer component={Paper} sx={{ mb: 3, overflowX: 'auto' }}>
                                <Table size="small" stickyHeader>
                                    <TableHead sx={{ backgroundColor: '#fff3e0' }}>
                                        <TableRow>
                                            <TableCell>#</TableCell>
                                            <TableCell>Cliente</TableCell>
                                            <TableCell align="right">💰 Total</TableCell>
                                            <TableCell align="right">📈 Ganancia</TableCell>
                                            <TableCell align="center">🛒</TableCell>
                                            <TableCell align="center">📦</TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {mejoresClientes.slice(0, 10).map((cliente, index) => (
                                            <TableRow key={cliente.nombre}>
                                                <TableCell>
                                                    {index === 0 && <StarIcon color="warning" fontSize="small" />}
                                                    {index === 1 && <StarIcon sx={{ color: '#c0c0c0' }} fontSize="small" />}
                                                    {index === 2 && <StarIcon sx={{ color: '#cd7f32' }} fontSize="small" />}
                                                    {index > 2 && index + 1}
                                                </TableCell>
                                                <TableCell>
                                                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                        <Avatar sx={{ width: 24, height: 24, bgcolor: '#667eea' }}>
                                                            <PersonIcon fontSize="small" />
                                                        </Avatar>
                                                        <Typography variant="body2" noWrap sx={{ maxWidth: { xs: 100, sm: 'none' } }}>
                                                            {cliente.nombre}
                                                        </Typography>
                                                    </Box>
                                                </TableCell>
                                                <TableCell align="right" sx={{ fontWeight: 'bold', color: '#2e7d32' }}>
                                                    ${cliente.totalCompras.toLocaleString()}
                                                </TableCell>
                                                <TableCell align="right" sx={{ color: '#4caf50' }}>
                                                    +${cliente.gananciaTotal.toLocaleString()}
                                                </TableCell>
                                                <TableCell align="center">
                                                    <Chip label={cliente.cantidadCompras} size="small" />
                                                </TableCell>
                                                <TableCell align="center">
                                                    <Chip label={cliente.productosComprados} size="small" variant="outlined" />
                                                </TableCell>
                                            </TableRow>
                                        ))}
                                        {mejoresClientes.length === 0 && (
                                            <TableRow>
                                                <TableCell colSpan={6} align="center">
                                                    No hay datos de clientes
                                                </TableCell>
                                            </TableRow>
                                        )}
                                    </TableBody>
                                </Table>
                            </TableContainer>

                            {/* Productos Más Vendidos */}
                            <Typography variant="h6" sx={{ mt: 3, mb: 2, display: 'flex', alignItems: 'center', gap: 1 }}>
                                <TrendingUpIcon color="success" />
                                🔥 Productos Más Vendidos
                            </Typography>

                            <TableContainer component={Paper} sx={{ mb: 3, overflowX: 'auto' }}>
                                <Table size="small" stickyHeader>
                                    <TableHead sx={{ backgroundColor: '#e8f5e9' }}>
                                        <TableRow>
                                            <TableCell>#</TableCell>
                                            <TableCell>Producto</TableCell>
                                            <TableCell align="center">📦 Cantidad</TableCell>
                                            <TableCell align="right">💰 Ventas</TableCell>
                                            <TableCell align="right">📈 Ganancia</TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {productosVendidos.slice(0, 10).map((producto, index) => (
                                            <TableRow key={producto.id}>
                                                <TableCell>{index + 1}</TableCell>
                                                <TableCell>
                                                    <Chip
                                                        label={producto.nombre}
                                                        size="small"
                                                        sx={{ fontWeight: 'bold', maxWidth: { xs: 120, sm: 'none' } }}
                                                    />
                                                </TableCell>
                                                <TableCell align="center">
                                                    <Chip
                                                        label={`${producto.cantidad}`}
                                                        color="primary"
                                                        size="small"
                                                    />
                                                </TableCell>
                                                <TableCell align="right" sx={{ fontWeight: 'bold' }}>
                                                    ${producto.ventas.toLocaleString()}
                                                </TableCell>
                                                <TableCell align="right" sx={{ color: '#4caf50' }}>
                                                    +${producto.ganancia.toLocaleString()}
                                                </TableCell>
                                            </TableRow>
                                        ))}
                                        {productosVendidos.length === 0 && (
                                            <TableRow>
                                                <TableCell colSpan={5} align="center">
                                                    No hay datos de productos vendidos
                                                </TableCell>
                                            </TableRow>
                                        )}
                                    </TableBody>
                                </Table>
                            </TableContainer>

                            {/* Resumen General */}
                            {ventas.length > 0 && (
                                <Paper sx={{ p: 2, mt: 2, backgroundColor: '#e3f2fd' }}>
                                    <Typography variant="subtitle2" gutterBottom fontWeight="bold">
                                        Resumen del período:
                                    </Typography>
                                    <Stack direction="column" spacing={1}>
                                        <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                            <Typography variant="caption" color="text.secondary">Total Ventas:</Typography>
                                            <Typography variant="body2" fontWeight="bold">{ventas.length}</Typography>
                                        </Box>
                                        <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                            <Typography variant="caption" color="text.secondary">Clientes únicos:</Typography>
                                            <Typography variant="body2" fontWeight="bold">{mejoresClientes.length}</Typography>
                                        </Box>
                                        <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                            <Typography variant="caption" color="text.secondary">Productos vendidos:</Typography>
                                            <Typography variant="body2" fontWeight="bold">{productosVendidos.length}</Typography>
                                        </Box>
                                        <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                                            <Typography variant="caption" color="text.secondary">Ganancia total:</Typography>
                                            <Typography variant="body2" fontWeight="bold" color="#4caf50">
                                                +${ventas.reduce((sum, v) => sum + (v.gananciaTotal || 0), 0).toLocaleString()}
                                            </Typography>
                                        </Box>
                                    </Stack>
                                </Paper>
                            )}
                        </>
                    )}
                </Box>
            </Drawer>
        </>
    );
};

export default EstadisticasVentas;