// src/Footer.js
import React from 'react';
import { Box, Typography, Chip, Avatar } from '@mui/material';
import { Code, Rocket, Favorite } from '@mui/icons-material';

const Footer = () => {
    return (
        <Box
            component="footer"
            sx={{
                mt: 'auto',
                py: { xs: 2, sm: 3 },
                px: { xs: 2, sm: 3 },
                position: 'relative',
                zIndex: 1,
                display: 'flex',
                justifyContent: 'center',
                alignItems: 'center'
            }}
        >
            {/* Chip principal más grande */}
            <Chip
                avatar={
                    <Avatar sx={{ bgcolor: 'transparent' }}>
                        <span style={{ fontSize: '1.2rem' }}>💀</span>
                    </Avatar>
                }
                label={
                    <Box sx={{
                        display: 'flex',
                        alignItems: 'center',
                        gap: 1.5,
                        py: 0.5,
                        px: { xs: 0.5, sm: 1 }
                    }}>
                        <Typography
                            component="span"
                            sx={{
                                fontWeight: 700,
                                fontSize: { xs: '0.85rem', sm: '0.95rem' },
                                background: 'linear-gradient(135deg, #1976d2, #9c27b0)',
                                backgroundClip: 'text',
                                WebkitBackgroundClip: 'text',
                                color: 'transparent',
                                display: 'flex',
                                alignItems: 'center',
                                gap: 1
                            }}
                        >
                            Powered by Pablo A.
                        </Typography>

                        {/* Separador visual */}
                        <Box
                            sx={{
                                width: 1,
                                height: 20,
                                bgcolor: 'rgba(156, 39, 176, 0.3)',
                                mx: 0.5
                            }}
                        />

                        {/* Año y emojis */}
                        <Typography
                            component="span"
                            sx={{
                                fontSize: { xs: '0.75rem', sm: '0.85rem' },
                                color: '#666',
                                display: 'flex',
                                alignItems: 'center',
                                gap: 0.5
                            }}
                        >
                            <Rocket sx={{ fontSize: '0.9rem', color: '#1976d2' }} />
                            2025
                            <Favorite sx={{ fontSize: '0.8rem', color: '#111011' }} />
                        </Typography>
                    </Box>
                }
                sx={{
                    height: 'auto',
                    py: 1,
                    px: 1.5,
                    borderRadius: '50px',
                    backgroundColor: 'rgba(255, 255, 255, 0.5)',
                    backdropFilter: 'blur(10px)',
                    border: '1px solid rgba(156, 39, 176, 0.3)',
                    boxShadow: '0 4px 15px rgba(0,0,0,0.1)',
                    transition: 'all 0.3s ease',
                    '&:hover': {
                        transform: 'translateY(-2px)',
                        backgroundColor: 'rgba(255, 255, 255, 0.7)',
                        border: '1px solid rgba(156, 39, 176, 0.5)',
                        boxShadow: '0 6px 20px rgba(156, 39, 176, 0.2)',
                        cursor: 'pointer'
                    },
                    '& .MuiChip-label': {
                        px: 2,
                        py: 0.5
                    }
                }}
                onClick={() => window.open('https://github.com', '_blank')} // Opcional: enlace a tu perfil
            />
        </Box>
    );
};

export default Footer;