// src/components/Ganancias/RegistroVentas.js
import React, { useState, useEffect } from 'react';
import {
    Box, Typography, TextField, Button, Paper, Table, TableBody, TableCell,
    TableContainer, TableHead, TableRow, IconButton, Chip, Alert, Snackbar,
    Autocomplete, InputAdornment, useMediaQuery, useTheme, Card, CardContent,
    Stack, Divider
} from '@mui/material';
import { ref, get, push, remove, update } from "firebase/database"; // ← Añadí push aquí
import { db } from "./firebaseConfig";
import AddIcon from '@mui/icons-material/Add';
import RemoveIcon from '@mui/icons-material/Remove';
import ShoppingCartIcon from '@mui/icons-material/ShoppingCart';
import PersonIcon from '@mui/icons-material/Person';
import AttachMoneyIcon from '@mui/icons-material/AttachMoney';
import DeleteIcon from '@mui/icons-material/Delete';

const RegistroVentas = ({ onVentaRegistrada }) => {
    const theme = useTheme();
    const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
    const isTablet = useMediaQuery(theme.breakpoints.between('sm', 'md'));

    const [productos, setProductos] = useState([]);
    const [clientes, setClientes] = useState([]);
    const [clienteInput, setClienteInput] = useState('');
    const [zonaVenta, setZonaVenta] = useState('');
    const [carrito, setCarrito] = useState([]);
    const [productoSeleccionado, setProductoSeleccionado] = useState(null);
    const [cantidad, setCantidad] = useState(1);
    const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });
    const [mostrarCarrito, setMostrarCarrito] = useState(false);

    useEffect(() => {
        cargarProductos();
        cargarClientes();
    }, []);

    const cargarProductos = async () => {
        const productosRef = ref(db, "productos");
        const snapshot = await get(productosRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const productosList = Object.entries(data).map(([id, producto]) => ({
                id,
                ...producto,
                label: `${producto.nombre} - $${producto.precioVenta.toLocaleString()}`
            }));
            setProductos(productosList);
        }
    };

    const cargarClientes = async () => {
        const clientesRef = ref(db, "clientes");
        const snapshot = await get(clientesRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const clientesList = Object.values(data);
            setClientes(clientesList);
        }
    };

    const guardarCliente = async (nombreCliente) => {
        if (!nombreCliente.trim()) return;

        const existe = clientes.some(c => c.nombre.toLowerCase() === nombreCliente.toLowerCase());
        if (!existe) {
            const clientesRef = ref(db, "clientes");
            const nuevoCliente = {
                nombre: nombreCliente,
                fechaRegistro: new Date().toISOString(),
                compras: 0
            };
            await push(clientesRef, nuevoCliente);
            await cargarClientes();
        }
    };

    const agregarAlCarrito = () => {
        if (!productoSeleccionado) {
            setSnackbar({ open: true, message: 'Selecciona un producto', severity: 'warning' });
            return;
        }

        const cantidadFinal = cantidad === 0 ? 1 : cantidad;

        const existe = carrito.find(item => item.id === productoSeleccionado.id);
        if (existe) {
            setCarrito(carrito.map(item =>
                item.id === productoSeleccionado.id
                    ? { ...item, cantidad: item.cantidad + cantidadFinal }
                    : item
            ));
        } else {
            setCarrito([...carrito, {
                ...productoSeleccionado,
                cantidad: cantidadFinal
            }]);
        }

        setProductoSeleccionado(null);
        setCantidad(1);
        setSnackbar({ open: true, message: 'Producto agregado al carrito', severity: 'success' });

        if (isMobile) {
            setMostrarCarrito(true);
        }
    };

    const eliminarDelCarrito = (id) => {
        setCarrito(carrito.filter(item => item.id !== id));
    };

    const actualizarCantidad = (id, nuevaCantidad) => {
        if (nuevaCantidad <= 0) {
            eliminarDelCarrito(id);
        } else {
            setCarrito(carrito.map(item =>
                item.id === id ? { ...item, cantidad: nuevaCantidad } : item
            ));
        }
    };

    const calcularTotal = () => {
        return carrito.reduce((sum, item) => sum + (item.precioVenta * item.cantidad), 0);
    };

    const calcularGananciaTotal = () => {
        return carrito.reduce((sum, item) => sum + ((item.precioVenta - item.precioCosto) * item.cantidad), 0);
    };

    const calcularCostoTotal = () => {
        return carrito.reduce((sum, item) => sum + (item.precioCosto * item.cantidad), 0);
    };

    const registrarVenta = async () => {
        if (!clienteInput.trim()) {
            setSnackbar({ open: true, message: 'Ingresa el nombre del cliente', severity: 'warning' });
            return;
        }
        if (carrito.length === 0) {
            setSnackbar({ open: true, message: 'Agrega productos al carrito', severity: 'warning' });
            return;
        }

        await guardarCliente(clienteInput);

        const totalVenta = calcularTotal();
        const gananciaTotal = calcularGananciaTotal();

        const ventaData = {
            cliente: clienteInput,
            zona: zonaVenta || "Sin zona",
            fecha: new Date().toISOString(),
            productos: carrito.map(item => ({
                id: item.id,
                nombre: item.nombre,
                precioCosto: item.precioCosto,
                precioVenta: item.precioVenta,
                cantidad: item.cantidad,
                ganancia: (item.precioVenta - item.precioCosto) * item.cantidad
            })),
            total: totalVenta,
            gananciaTotal: gananciaTotal,
            costoTotal: calcularCostoTotal()
        };

        try {
            await push(ref(db, "ventas"), ventaData);

            await push(ref(db, "ganancias/historial"), {
                mes: new Date().getMonth(),
                total: gananciaTotal,
                gananciaNeta: gananciaTotal,
                fechaGanancia: new Date().toISOString(),
                zona: zonaVenta || "Sin zona",
                cliente: clienteInput,
                productos: carrito.map(p => `${p.nombre} x${p.cantidad}`).join(', '),
                tipo: "venta"
            });

            setSnackbar({
                open: true,
                message: `¡Venta registrada! Ganancia: $${gananciaTotal.toLocaleString()}`,
                severity: 'success'
            });

            setClienteInput('');
            setZonaVenta('');
            setCarrito([]);
            setProductoSeleccionado(null);
            setCantidad(1);
            setMostrarCarrito(false);

            if (onVentaRegistrada) onVentaRegistrada();

        } catch (error) {
            console.error("Error al registrar venta:", error);
            setSnackbar({ open: true, message: 'Error al registrar la venta', severity: 'error' });
        }
    };

    // Función para editar venta (corregida - sin usar nuevosDatos)
    const editarVenta = async (ventaId, datosActualizados) => {
        try {
            const ventaRef = ref(db, `ventas/${ventaId}`);
            await update(ventaRef, datosActualizados);

            setSnackbar({ open: true, message: 'Venta actualizada correctamente', severity: 'success' });

            if (onVentaRegistrada) onVentaRegistrada();
        } catch (error) {
            console.error("Error al editar venta:", error);
            setSnackbar({ open: true, message: 'Error al actualizar la venta', severity: 'error' });
        }
    };

    // Función para eliminar venta (corregida)
    const eliminarVenta = async (ventaId, ventaData) => {
        if (window.confirm('¿Estás seguro de eliminar esta venta?')) {
            try {
                const ventaRef = ref(db, `ventas/${ventaId}`);
                await remove(ventaRef);

                // Buscar y eliminar la ganancia asociada
                const gananciasRef = ref(db, "ganancias/historial");
                const snapshot = await get(gananciasRef);
                if (snapshot.exists()) {
                    const data = snapshot.val();
                    for (const [key, value] of Object.entries(data)) {
                        // Comparar por fecha y cliente
                        if (value.cliente === ventaData?.cliente &&
                            new Date(value.fechaGanancia).toLocaleDateString() === new Date(ventaData?.fecha).toLocaleDateString()) {
                            await remove(ref(db, `ganancias/historial/${key}`));
                            break;
                        }
                    }
                }

                setSnackbar({ open: true, message: 'Venta eliminada correctamente', severity: 'success' });
                if (onVentaRegistrada) onVentaRegistrada();
            } catch (error) {
                console.error("Error al eliminar venta:", error);
                setSnackbar({ open: true, message: 'Error al eliminar la venta', severity: 'error' });
            }
        }
    };

    return (
        <Box sx={{ mt: 2, px: isMobile ? 1 : 2 }}>
            <Paper sx={{
                p: isMobile ? 1.5 : 2,
                mb: 2,
                backgroundColor: '#fff3e0',
                borderRadius: isMobile ? 2 : 1
            }}>
                <Typography variant="h5" sx={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 1,
                    mb: 2,
                    fontSize: isMobile ? '1.2rem' : '1.5rem'
                }}>
                    <ShoppingCartIcon color="warning" /> Nueva Venta
                </Typography>

                {/* Datos del cliente - Responsive */}
                <Stack spacing={2} sx={{ mb: 2 }}>
                    <Autocomplete
                        freeSolo
                        options={clientes.map(c => c.nombre)}
                        value={clienteInput}
                        onInputChange={(event, newValue) => setClienteInput(newValue || '')}
                        onChange={(event, newValue) => setClienteInput(newValue || '')}
                        renderInput={(params) => (
                            <TextField
                                {...params}
                                label="Nombre del cliente"
                                placeholder="Escribe el nombre..."
                                size={isMobile ? "small" : "medium"}
                                InputProps={{
                                    ...params.InputProps,
                                    startAdornment: (
                                        <InputAdornment position="start">
                                            <PersonIcon sx={{ color: 'gray', fontSize: isMobile ? 18 : 24 }} />
                                        </InputAdornment>
                                    ),
                                }}
                            />
                        )}
                    />

                    <TextField
                        label="Zona (opcional)"
                        value={zonaVenta}
                        onChange={(e) => setZonaVenta(e.target.value)}
                        size={isMobile ? "small" : "medium"}
                        placeholder="Ej: Centro, Norte"
                    />
                </Stack>

                {/* Agregar productos - Responsive */}
                <Box sx={{ mb: 2 }}>
                    <Typography variant="subtitle2" gutterBottom sx={{ fontSize: isMobile ? '0.8rem' : '0.9rem' }}>
                        Agregar productos:
                    </Typography>

                    <Stack spacing={1.5}>
                        <Autocomplete
                            freeSolo
                            options={productos}
                            value={productoSeleccionado}
                            onChange={(event, newValue) => setProductoSeleccionado(newValue)}
                            getOptionLabel={(option) => typeof option === 'string' ? option : option.nombre}
                            renderOption={(props, option) => (
                                <li {...props}>
                                    <Box>
                                        <Typography variant="body2">{option.nombre}</Typography>
                                        <Typography variant="caption" color="text.secondary">
                                            ${option.precioVenta.toLocaleString()} | +${option.ganancia?.toLocaleString() || ((option.precioVenta - option.precioCosto)?.toLocaleString() || 0)}
                                        </Typography>
                                    </Box>
                                </li>
                            )}
                            renderInput={(params) => (
                                <TextField
                                    {...params}
                                    label="Buscar producto"
                                    placeholder="Escribe el nombre..."
                                    size={isMobile ? "small" : "medium"}
                                />
                            )}
                        />

                        <Box sx={{ display: 'flex', gap: 1, alignItems: 'center' }}>
                            <TextField
                                label="Cantidad"
                                type="number"
                                value={cantidad === 0 ? '' : cantidad}
                                onChange={(e) => {
                                    const valor = e.target.value;
                                    if (valor === '') {
                                        setCantidad(0);
                                    } else {
                                        const numero = parseInt(valor);
                                        if (!isNaN(numero) && numero >= 0) {
                                            setCantidad(numero);
                                        }
                                    }
                                }}
                                onBlur={() => {
                                    if (cantidad === 0 || cantidad === '') {
                                        setCantidad(1);
                                    }
                                }}
                                size={isMobile ? "small" : "medium"}
                                sx={{ flex: 1 }}
                                inputProps={{
                                    min: 1,
                                    style: { textAlign: 'center' }
                                }}
                            />
                            <Button
                                variant="contained"
                                onClick={agregarAlCarrito}
                                startIcon={<AddIcon />}
                                disabled={!productoSeleccionado}
                                size={isMobile ? "small" : "medium"}
                                sx={{ flex: 2 }}
                            >
                                Agregar
                            </Button>
                        </Box>
                    </Stack>
                </Box>

                {/* Botón para ver carrito en móvil */}
                {carrito.length > 0 && isMobile && !mostrarCarrito && (
                    <Button
                        fullWidth
                        variant="outlined"
                        onClick={() => setMostrarCarrito(true)}
                        sx={{ mb: 2 }}
                    >
                        Ver Carrito ({carrito.length} productos) - ${calcularTotal().toLocaleString()}
                    </Button>
                )}

                {/* Carrito - Responsive */}
                {(carrito.length > 0 && (!isMobile || mostrarCarrito)) && (
                    <>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                            <Typography variant="subtitle1">Carrito</Typography>
                            {isMobile && (
                                <Button size="small" onClick={() => setMostrarCarrito(false)}>
                                    Cerrar
                                </Button>
                            )}
                        </Box>

                        {/* Versión móvil: tarjetas en lugar de tabla */}
                        {isMobile ? (
                            <Stack spacing={1} sx={{ mb: 2, maxHeight: 300, overflow: 'auto' }}>
                                {carrito.map((item) => (
                                    <Card key={item.id} sx={{ p: 1 }}>
                                        <CardContent sx={{ p: 1, '&:last-child': { pb: 1 } }}>
                                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 1 }}>
                                                <Typography variant="body2" fontWeight="bold">{item.nombre}</Typography>
                                                <IconButton size="small" color="error" onClick={() => eliminarDelCarrito(item.id)}>
                                                    <DeleteIcon fontSize="small" />
                                                </IconButton>
                                            </Box>
                                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                                <Typography variant="body2">${item.precioVenta.toLocaleString()} c/u</Typography>
                                                <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                                    <IconButton size="small" onClick={() => actualizarCantidad(item.id, item.cantidad - 1)}>
                                                        <RemoveIcon fontSize="small" />
                                                    </IconButton>
                                                    <Typography variant="body2">{item.cantidad}</Typography>
                                                    <IconButton size="small" onClick={() => actualizarCantidad(item.id, item.cantidad + 1)}>
                                                        <AddIcon fontSize="small" />
                                                    </IconButton>
                                                </Box>
                                                <Typography variant="body2" fontWeight="bold">
                                                    ${(item.precioVenta * item.cantidad).toLocaleString()}
                                                </Typography>
                                            </Box>
                                        </CardContent>
                                    </Card>
                                ))}
                            </Stack>
                        ) : (
                            <TableContainer component={Paper} sx={{ mb: 2 }}>
                                <Table size="small">
                                    <TableHead sx={{ backgroundColor: '#f5f5f5' }}>
                                        <TableRow>
                                            <TableCell>Producto</TableCell>
                                            <TableCell align="right">Precio</TableCell>
                                            <TableCell align="center">Cantidad</TableCell>
                                            <TableCell align="right">Subtotal</TableCell>
                                            <TableCell align="center"></TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {carrito.map((item) => (
                                            <TableRow key={item.id}>
                                                <TableCell>
                                                    <Chip label={item.nombre} size="small" />
                                                </TableCell>
                                                <TableCell align="right">${item.precioVenta.toLocaleString()}</TableCell>
                                                <TableCell align="center">
                                                    <IconButton size="small" onClick={() => actualizarCantidad(item.id, item.cantidad - 1)}>
                                                        <RemoveIcon fontSize="small" />
                                                    </IconButton>
                                                    {item.cantidad}
                                                    <IconButton size="small" onClick={() => actualizarCantidad(item.id, item.cantidad + 1)}>
                                                        <AddIcon fontSize="small" />
                                                    </IconButton>
                                                </TableCell>
                                                <TableCell align="right">
                                                    ${(item.precioVenta * item.cantidad).toLocaleString()}
                                                </TableCell>
                                                <TableCell align="center">
                                                    <IconButton size="small" color="error" onClick={() => eliminarDelCarrito(item.id)}>
                                                        <DeleteIcon fontSize="small" />
                                                    </IconButton>
                                                </TableCell>
                                            </TableRow>
                                        ))}
                                    </TableBody>
                                </Table>
                            </TableContainer>
                        )}

                        {/* Resumen - Responsive */}
                        <Paper sx={{ p: isMobile ? 1.5 : 2, backgroundColor: '#e8f5e9', mb: 2 }}>
                            <Stack direction={isMobile ? 'column' : 'row'} spacing={isMobile ? 1 : 2} divider={<Divider orientation={isMobile ? "horizontal" : "vertical"} flexItem />}>
                                <Box sx={{ flex: 1, textAlign: isMobile ? 'center' : 'left' }}>
                                    <Typography variant="caption" color="text.secondary">Costo total:</Typography>
                                    <Typography variant={isMobile ? "body1" : "h6"}>${calcularCostoTotal().toLocaleString()}</Typography>
                                </Box>
                                <Box sx={{ flex: 1, textAlign: isMobile ? 'center' : 'left' }}>
                                    <Typography variant="caption" color="text.secondary">Venta total:</Typography>
                                    <Typography variant={isMobile ? "body1" : "h6"} color="primary">${calcularTotal().toLocaleString()}</Typography>
                                </Box>
                                <Box sx={{ flex: 1, textAlign: isMobile ? 'center' : 'left' }}>
                                    <Typography variant="caption" color="text.secondary">Ganancia:</Typography>
                                    <Typography variant={isMobile ? "body1" : "h5"} color="#4caf50" fontWeight="bold">
                                        +${calcularGananciaTotal().toLocaleString()}
                                    </Typography>
                                </Box>
                            </Stack>
                        </Paper>

                        <Button
                            fullWidth
                            variant="contained"
                            color="success"
                            size={isMobile ? "medium" : "large"}
                            onClick={registrarVenta}
                            startIcon={<AttachMoneyIcon />}
                            sx={{ py: isMobile ? 1.5 : 1 }}
                        >
                            Registrar Venta
                        </Button>
                    </>
                )}
            </Paper>

            <Snackbar
                open={snackbar.open}
                autoHideDuration={2000}
                onClose={() => setSnackbar({ ...snackbar, open: false })}
                anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
            >
                <Alert severity={snackbar.severity} sx={{ fontSize: isMobile ? '0.8rem' : '0.9rem' }}>
                    {snackbar.message}
                </Alert>
            </Snackbar>
        </Box>
    );
};

export default RegistroVentas;