// src/EstadisticasPage.js
import React, { useState, useEffect } from 'react';
import { Box, Typography, Grid, Card, CardContent } from '@mui/material';
import { ref, get } from "firebase/database";
import { db } from "./firebaseConfig";
import EstadisticasZona from './EstadisticasZona';
import ComparativaMensual from './ComparativaMensual';
import Proyecciones from './Proyecciones';
import EstadisticasVentas from './EstadisticasVentas';
import ComparativaAnual from './ComparativaAnual';

const obtenerNombreMes = (mes) => {
  const meses = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
    "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
  return meses[mes];
};

const EstadisticasPage = () => {
    const [gananciasPorDia, setGananciasPorDia] = useState([]);
    const [gananciasPorMes, setGananciasPorMes] = useState([]);
    const [gananciasPorMesCompleto, setGananciasPorMesCompleto] = useState([]);
    const [totalGanancias, setTotalGanancias] = useState(0);
    const [diasTrabajados, setDiasTrabajados] = useState(0);

    const cargarGanancias = async () => {
        const gananciasRef = ref(db, "ganancias/historial");
        const snapshot = await get(gananciasRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const currentYear = new Date().getFullYear();
            const currentMonth = new Date().getMonth();

            const mesFiltrado = Object.values(data).filter(g => {
                const fecha = new Date(g.fechaGanancia);
                return fecha.getMonth() === currentMonth && fecha.getFullYear() === currentYear;
            });

            const gananciasAgrupadas = Object.values(data).reduce((acc, ganancia) => {
                const mes = new Date(ganancia.fechaGanancia).getMonth();
                const anio = new Date(ganancia.fechaGanancia).getFullYear();
                const key = `${anio}-${mes}`;
                if (!acc[key]) {
                    acc[key] = {
                        mes,
                        anio,
                        total: 0,
                        diasTrabajados: new Set()
                    };
                }
                acc[key].total += ganancia.total;
                acc[key].diasTrabajados.add(new Date(ganancia.fechaGanancia).toLocaleDateString());
                return acc;
            }, {});

            const gananciasOrdenadas = Object.values(gananciasAgrupadas).sort((a, b) => {
                if (a.anio !== b.anio) return b.anio - a.anio;
                return b.mes - a.mes;
            });

            setGananciasPorMesCompleto(gananciasOrdenadas);
            setGananciasPorMes(gananciasOrdenadas.filter(m => m.anio === currentYear));
            setGananciasPorDia(mesFiltrado);
            setTotalGanancias(mesFiltrado.reduce((sum, g) => sum + g.total, 0));
            setDiasTrabajados(new Set(mesFiltrado.map(g => new Date(g.fechaGanancia).toLocaleDateString())).size);
        }
    };

    useEffect(() => { cargarGanancias(); }, []);

  return (
    <Box>
      <Typography variant="h4" fontWeight="bold" gutterBottom>📊 Estadísticas</Typography>
      
      <Grid container spacing={3} sx={{ mb: 3 }}>
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography color="textSecondary">Ganancias del Mes</Typography>
              <Typography variant="h4" fontWeight="bold" color="#2e7d32">${totalGanancias.toLocaleString()}</Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} md={6}>
          <Card>
            <CardContent>
              <Typography color="textSecondary">Promedio Diario</Typography>
              <Typography variant="h4" fontWeight="bold">${diasTrabajados > 0 ? (totalGanancias / diasTrabajados).toLocaleString() : 0}</Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>
        
      <EstadisticasZona gananciasPorDia={gananciasPorDia} />
      <Proyecciones totalGanancias={totalGanancias} diasTrabajados={diasTrabajados} gananciasPorMes={gananciasPorMes} mesActual={new Date().getMonth()} />
      <ComparativaMensual gananciasPorMes={gananciasPorMes} obtenerNombreMes={obtenerNombreMes} />
      <EstadisticasVentas />
          <ComparativaAnual
              gananciasPorMesCompleto={gananciasPorMesCompleto}
          />
    </Box>
  );
};

export default EstadisticasPage;