// src/Ganancias.js
import React, { useState, useEffect } from 'react';
import { Box, Typography, Button, Paper, Grid, Card, CardContent, IconButton } from '@mui/material';
import { Visibility, VisibilityOff } from '@mui/icons-material';
import { ref, get } from "firebase/database";
import { db } from "./firebaseConfig";
import RegistroVentas from './RegistroVentas';
import WidgetCobrosPendientes from './WidgetCobrosPendientes';

const obtenerNombreMes = (mes) => {
    const meses = ["Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
        "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"];
    return meses[mes];
};

const Ganancias = () => {
    const [totalGanancias, setTotalGanancias] = useState(0);
    const [gananciasPorDia, setGananciasPorDia] = useState([]);
    const [diasTrabajados, setDiasTrabajados] = useState(0);
    const [gananciasPorMes, setGananciasPorMes] = useState([]);
    const [mostrarPrevios, setMostrarPrevios] = useState(false);

    // Nuevos estados para costos y compras
    const [totalRecaudadoCosto, setTotalRecaudadoCosto] = useState(0);
    const [totalVentaMenosCosto, setTotalVentaMenosCosto] = useState(0);
    const [costoAcumuladoCompras, setCostoAcumuladoCompras] = useState(0);

    // Estados para controlar la visibilidad de cada cuadro
    const [mostrarGananciasMes, setMostrarGananciasMes] = useState(true);
    const [mostrarMejorMes, setMostrarMejorMes] = useState(true);
    const [mostrarPromedioDiario, setMostrarPromedioDiario] = useState(true);
    const [mostrarDineroCompras, setMostrarDineroCompras] = useState(true);
    const [mostrarGananciaNeta, setMostrarGananciaNeta] = useState(true);
    const [mostrarVentasBrutas, setMostrarVentasBrutas] = useState(true);

    const cargarGanancias = async () => {
        const gananciasRef = ref(db, "ganancias/historial");
        const snapshot = await get(gananciasRef);
        if (snapshot.exists()) {
            const data = snapshot.val();
            const currentYear = new Date().getFullYear();
            const currentMonth = new Date().getMonth();

            const mesFiltrado = Object.values(data).filter(g => {
                const fecha = new Date(g.fechaGanancia);
                return fecha.getMonth() === currentMonth && fecha.getFullYear() === currentYear;
            });

            // Calcular costos del mes actual
            // IMPORTANTE: Ahora vamos a leer las ventas reales para obtener los costos
            let sumaCostos = 0;
            let sumaVentas = 0;
            let sumaGananciasReales = 0;

            // Para cada ganancia registrada, buscamos la venta original para obtener el costo
            for (const ganancia of mesFiltrado) {
                // Buscar la venta correspondiente por fecha y cliente
                const ventasRef = ref(db, "ventas");
                const ventasSnapshot = await get(ventasRef);

                if (ventasSnapshot.exists()) {
                    const ventas = ventasSnapshot.val();
                    // Buscar la venta que coincida con esta ganancia
                    const ventaEncontrada = Object.values(ventas).find(venta =>
                        venta.cliente === ganancia.cliente &&
                        new Date(venta.fecha).toLocaleDateString() === new Date(ganancia.fechaGanancia).toLocaleDateString()
                    );

                    if (ventaEncontrada && ventaEncontrada.costoTotal) {
                        sumaCostos += ventaEncontrada.costoTotal;
                        sumaVentas += ventaEncontrada.total;
                        sumaGananciasReales += ventaEncontrada.gananciaTotal;
                    } else if (ganancia.total) {
                        // Si no encontramos la venta, usamos un porcentaje estimado (40% de ganancia = 60% costo)
                        const costoEstimado = ganancia.total * 0.6; // 60% del total es costo
                        sumaCostos += costoEstimado;
                        sumaVentas += ganancia.total;
                        sumaGananciasReales += ganancia.total - costoEstimado;
                    }
                } else {
                    // Fallback: usar porcentaje si no hay ventas
                    const costoEstimado = ganancia.total * 0.6;
                    sumaCostos += costoEstimado;
                    sumaVentas += ganancia.total;
                    sumaGananciasReales += ganancia.total - costoEstimado;
                }
            }

            setTotalRecaudadoCosto(sumaCostos);
            setTotalVentaMenosCosto(sumaGananciasReales);
            setCostoAcumuladoCompras(sumaCostos);

            const gananciasAgrupadas = Object.values(data).reduce((acc, ganancia) => {
                const mes = new Date(ganancia.fechaGanancia).getMonth();
                const anio = new Date(ganancia.fechaGanancia).getFullYear();
                const key = `${anio}-${mes}`;
                if (!acc[key]) acc[key] = { mes, anio, total: 0, costoTotal: 0, diasTrabajados: new Set() };
                acc[key].total += ganancia.total;
                acc[key].diasTrabajados.add(new Date(ganancia.fechaGanancia).toLocaleDateString());
                return acc;
            }, {});

            const gananciasOrdenadas = Object.values(gananciasAgrupadas).sort((a, b) => {
                if (a.anio !== b.anio) return b.anio - a.anio;
                return b.mes - a.mes;
            });

            setGananciasPorMes(gananciasOrdenadas.filter(m => m.anio === currentYear));
            setGananciasPorDia(mesFiltrado);
            setTotalGanancias(mesFiltrado.reduce((sum, g) => sum + g.total, 0));
            setDiasTrabajados(new Set(mesFiltrado.map(g => new Date(g.fechaGanancia).toLocaleDateString())).size);
        }
    };

    useEffect(() => { cargarGanancias(); }, []);

    const refrescarDatos = () => cargarGanancias();

    const mejorMes = gananciasPorMes.length > 0 ?
        gananciasPorMes.reduce((prev, current) => prev.total > current.total ? prev : current) : null;

    // Función para formatear valores ocultos
    const formatearValorOculto = (mostrar, valor, tipo = 'moneda') => {
        if (!mostrar) return '••••••';
        if (tipo === 'moneda') return `$${valor.toLocaleString()}`;
        return valor;
    };

    return (
        <Box>
            <WidgetCobrosPendientes />

            <Grid container spacing={3} sx={{ mb: 3 }}>
                <Grid item xs={12} md={4}>
                    <Card>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography color="textSecondary">Ganancias del Mes</Typography>
                                <IconButton
                                    size="small"
                                    onClick={() => setMostrarGananciasMes(!mostrarGananciasMes)}
                                    sx={{ ml: 1 }}
                                >
                                    {mostrarGananciasMes ? <Visibility /> : <VisibilityOff />}
                                </IconButton>
                            </Box>
                            <Typography variant="h4" fontWeight="bold" color="#2e7d32">
                                {formatearValorOculto(mostrarGananciasMes, totalGanancias)}
                            </Typography>
                            <Typography variant="body2">Días trabajados: {diasTrabajados}</Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Card>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography color="textSecondary">Mejor Mes</Typography>
                                <IconButton
                                    size="small"
                                    onClick={() => setMostrarMejorMes(!mostrarMejorMes)}
                                    sx={{ ml: 1 }}
                                >
                                    {mostrarMejorMes ? <Visibility /> : <VisibilityOff />}
                                </IconButton>
                            </Box>
                            {mejorMes && (
                                <>
                                    <Typography variant="h6" fontWeight="bold">
                                        {obtenerNombreMes(mejorMes.mes)} {mejorMes.anio}
                                    </Typography>
                                    <Typography variant="body2" color="#2e7d32">
                                        {formatearValorOculto(mostrarMejorMes, mejorMes.total)}
                                    </Typography>
                                </>
                            )}
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Card>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography color="textSecondary">Promedio Diario</Typography>
                                <IconButton
                                    size="small"
                                    onClick={() => setMostrarPromedioDiario(!mostrarPromedioDiario)}
                                    sx={{ ml: 1 }}
                                >
                                    {mostrarPromedioDiario ? <Visibility /> : <VisibilityOff />}
                                </IconButton>
                            </Box>
                            <Typography variant="h6" fontWeight="bold">
                                {formatearValorOculto(mostrarPromedioDiario, diasTrabajados > 0 ? (totalGanancias / diasTrabajados) : 0)}
                            </Typography>
                            <Typography variant="body2">por día trabajado</Typography>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            {/* Nuevo cuadro de dinero para compras */}
            <Grid container spacing={3} sx={{ mb: 3 }}>
                <Grid item xs={12} md={4}>
                    <Card sx={{ bgcolor: '#e8f5e9' }}>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography color="textSecondary" variant="body2">💰 Dinero para Compras</Typography>
                                <IconButton
                                    size="small"
                                    onClick={() => setMostrarDineroCompras(!mostrarDineroCompras)}
                                    sx={{ ml: 1 }}
                                >
                                    {mostrarDineroCompras ? <Visibility /> : <VisibilityOff />}
                                </IconButton>
                            </Box>
                            <Typography variant="h5" fontWeight="bold" color="#1565c0">
                                {formatearValorOculto(mostrarDineroCompras, totalRecaudadoCosto)}
                            </Typography>
                            <Typography variant="caption">Costo total de productos vendidos (para reinversión)</Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Card sx={{ bgcolor: '#fff3e0' }}>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography color="textSecondary" variant="body2">📊 Ganancia Real Neta</Typography>
                                <IconButton
                                    size="small"
                                    onClick={() => setMostrarGananciaNeta(!mostrarGananciaNeta)}
                                    sx={{ ml: 1 }}
                                >
                                    {mostrarGananciaNeta ? <Visibility /> : <VisibilityOff />}
                                </IconButton>
                            </Box>
                            <Typography variant="h5" fontWeight="bold" color="#2e7d32">
                                {formatearValorOculto(mostrarGananciaNeta, totalVentaMenosCosto)}
                            </Typography>
                            <Typography variant="caption">(Total ventas) - (Costo total) del mes</Typography>
                        </CardContent>
                    </Card>
                </Grid>
                <Grid item xs={12} md={4}>
                    <Card sx={{ bgcolor: '#e3f2fd' }}>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                <Typography color="textSecondary" variant="body2">🔄 Total Ventas Brutas</Typography>
                                <IconButton
                                    size="small"
                                    onClick={() => setMostrarVentasBrutas(!mostrarVentasBrutas)}
                                    sx={{ ml: 1 }}
                                >
                                    {mostrarVentasBrutas ? <Visibility /> : <VisibilityOff />}
                                </IconButton>
                            </Box>
                            <Typography variant="h5" fontWeight="bold" color="#ed6c02">
                                {formatearValorOculto(mostrarVentasBrutas, totalRecaudadoCosto + totalVentaMenosCosto)}
                            </Typography>
                            <Typography variant="caption">Total recaudado en ventas (costo + ganancia)</Typography>
                        </CardContent>
                    </Card>
                </Grid>
            </Grid>

            <RegistroVentas onVentaRegistrada={refrescarDatos} />

            <Typography variant="h6" sx={{ mt: 3, mb: 2 }}>📋 Ingresos Diarios</Typography>
            {gananciasPorDia.length === 0 ? (
                <Typography textAlign="center">No hay ganancias registradas este mes.</Typography>
            ) : (
                gananciasPorDia.sort((a, b) => b.total - a.total).map((g, index) => (
                    <Paper key={index} sx={{ p: 2, mb: 1 }}>
                        <Box sx={{ display: 'flex', justifyContent: 'space-between' }}>
                            <Box>
                                <Typography fontWeight="bold">{new Date(g.fechaGanancia).toLocaleDateString()}</Typography>
                                <Typography variant="body2">👤 Cliente: {g.cliente || "No especificado"}</Typography>
                                {g.zona && <Typography variant="body2">📍 Zona: {g.zona}</Typography>}
                                {g.productos && (
                                    <Typography variant="body2" color="textSecondary">
                                        📦 {g.productos}
                                    </Typography>
                                )}
                            </Box>
                            <Typography fontWeight="bold" color="#2e7d32">${g.total.toLocaleString()}</Typography>
                        </Box>
                    </Paper>
                ))
            )}

            <Button onClick={() => setMostrarPrevios(!mostrarPrevios)} variant="outlined" sx={{ mt: 3 }}>
                {mostrarPrevios ? 'Ocultar' : 'Mostrar'} Historial de meses
            </Button>

            {mostrarPrevios && (
                <Box sx={{ mt: 3 }}>
                    <Typography variant="h6">Historial de Ganancias</Typography>
                    {gananciasPorMes.map((mes, idx) => (
                        <Paper key={idx} sx={{ p: 2, my: 1 }}>
                            <Typography fontWeight="bold">
                                {obtenerNombreMes(mes.mes)} {mes.anio}: ${mes.total.toLocaleString()}
                            </Typography>
                            <Typography variant="body2">Días trabajados: {mes.diasTrabajados.size}</Typography>
                        </Paper>
                    ))}
                </Box>
            )}
        </Box>
    );
};

export default Ganancias;