// src/App.js
import React from 'react';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import Layout from './Layout';
import Ganancias from './Ganancias';
import VentasPage from './VentasPage';
import ProductosPage from './ProductosPage';
import EstadisticasPage from './EstadisticasPage';
import CobrosPage from './CobrosPage';

const theme = createTheme({
  typography: {
    // Fuente general (para textos que no sean títulos)
    fontFamily: 'Poppins, sans-serif',

    // Configuración específica para cada nivel de título
    h1: {
      fontFamily: '"Fugaz One", cursive',
      fontWeight: 400, // Fugaz One generalmente se ve mejor con peso normal
      fontSize: '3rem',
      letterSpacing: '1px',
    },
    h2: {
      fontFamily: '"Fugaz One", cursive',
      fontWeight: 400,
      fontSize: '2.5rem',
      letterSpacing: '0.5px',
    },
    h3: {
      fontFamily: '"Maven pro", cursive',
      fontWeight: 400,
      fontSize: '2rem',
    },
    h4: {
      fontFamily: 'Maven pro, sans-serif',
      fontWeight: 600,
    },
    h5: {
      fontFamily: 'Maven pro, sans-serif',
      fontWeight: 400,
    },
    h6: {
      fontFamily: 'Poppins, sans-serif',
      fontWeight: 600,
    },
    body1: {
      fontFamily: 'Poppins, sans-serif',
    },
    body2: {
      fontFamily: 'Poppins, sans-serif',
    },
    button: {
      fontFamily: 'Poppins, sans-serif',
      fontWeight: 600,
    },
  },

  palette: {
    primary: { main: '#1976d2' },
    secondary: { main: '#dc004e' },
    background: {
      default: '#FFF9E6',
      paper: '#FFFDF5',
    },
  },

  components: {
    MuiCssBaseline: {
      styleOverrides: {
        body: {
          fontFamily: 'Poppins, sans-serif',
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          backgroundColor: '#FFFDF5',
          backgroundImage: 'linear-gradient(135deg, #FFFDF5 0%, #FFF9E6 100%)',
          transition: 'all 0.3s ease',
          '&:hover': {
            transform: 'translateY(-2px)',
            boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
          },
        },
      },
    },
    MuiCard: {
      styleOverrides: {
        root: {
          backgroundColor: '#FFFDF5',
          borderRadius: '12px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.06)',
          transition: 'all 0.3s ease',
          '&:hover': {
            transform: 'translateY(-2px)',
            boxShadow: '0 6px 16px rgba(0,0,0,0.1)',
          },
        },
      },
    },
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: '8px',
          textTransform: 'none',
          fontWeight: 600,
        },
      },
    },
  },
});

function App() {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <Router>
        <Layout>
          <Routes>
            <Route path="/" element={<Ganancias />} />
            <Route path="/ventas" element={<VentasPage />} />
            <Route path="/productos" element={<ProductosPage />} />
            <Route path="/estadisticas" element={<EstadisticasPage />} />
            <Route path="/cobros" element={<CobrosPage />} />
          </Routes>
        </Layout>
      </Router>
    </ThemeProvider>
  );
}

export default App;