// src/ComparativaAnual.js
import React, { useState, useEffect, useRef } from 'react';
import {
    Box,
    Typography,
    Paper,
    Grid,
    Card,
    CardContent,
    FormControl,
    InputLabel,
    Select,
    MenuItem,
    ToggleButton,
    ToggleButtonGroup,
    Chip,
    Table,
    TableBody,
    TableCell,
    TableContainer,
    TableHead,
    TableRow
} from '@mui/material';
import {
    TrendingUp,
    TrendingDown,
    CompareArrows,
    BarChart as BarChartIcon,
    CalendarToday
} from '@mui/icons-material';
import { Chart, registerables } from 'chart.js';

Chart.register(...registerables);

const ComparativaAnual = ({ gananciasPorMesCompleto = [] }) => {
    const chartRef = useRef(null);
    const chartInstance = useRef(null);

    const [tipoComparativa, setTipoComparativa] = useState('ganancias');
    const [modoComparativa, setModoComparativa] = useState('anual');
    const [anio1, setAnio1] = useState(new Date().getFullYear());
    const [anio2, setAnio2] = useState(new Date().getFullYear() - 1);
    const [mesSeleccionado, setMesSeleccionado] = useState(new Date().getMonth());
    const [datosComparativa, setDatosComparativa] = useState(null);
    const [porcentajeCambio, setPorcentajeCambio] = useState(null);

    const meses = [
        "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
        "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
    ];

    const añosDisponibles = Array.from(new Set(gananciasPorMesCompleto.map(m => m.anio))).sort((a, b) => b - a);

    // Calcular comparativa anual
    const calcularComparativaAnual = () => {
        const datosAnio1 = gananciasPorMesCompleto.filter(m => m.anio === anio1);
        const datosAnio2 = gananciasPorMesCompleto.filter(m => m.anio === anio2);

        const totalAnio1 = datosAnio1.reduce((sum, m) => sum + m.total, 0);
        const totalAnio2 = datosAnio2.reduce((sum, m) => sum + m.total, 0);

        const diferencia = totalAnio1 - totalAnio2;
        const porcentaje = totalAnio2 !== 0 ? ((diferencia / totalAnio2) * 100) : 0;

        const datosPorMes = meses.map((_, index) => {
            const mesAnio1 = datosAnio1.find(m => m.mes === index);
            const mesAnio2 = datosAnio2.find(m => m.mes === index);
            return {
                mes: index,
                nombre: meses[index],
                anio1: mesAnio1?.total || 0,
                anio2: mesAnio2?.total || 0,
                diferencia: (mesAnio1?.total || 0) - (mesAnio2?.total || 0)
            };
        });

        setDatosComparativa({
            totalAnio1,
            totalAnio2,
            diferencia,
            porcentaje,
            datosPorMes
        });
        setPorcentajeCambio(porcentaje);
    };

    // Calcular comparativa mensual
    const calcularComparativaMensual = () => {
        const datosMesAnio1 = gananciasPorMesCompleto.find(m => m.anio === anio1 && m.mes === mesSeleccionado);
        const datosMesAnio2 = gananciasPorMesCompleto.find(m => m.anio === anio2 && m.mes === mesSeleccionado);

        const totalAnio1 = datosMesAnio1?.total || 0;
        const totalAnio2 = datosMesAnio2?.total || 0;
        const diferencia = totalAnio1 - totalAnio2;
        const porcentaje = totalAnio2 !== 0 ? ((diferencia / totalAnio2) * 100) : 0;

        setDatosComparativa({
            totalAnio1,
            totalAnio2,
            diferencia,
            porcentaje,
            mes: meses[mesSeleccionado],
            mesAnio1: datosMesAnio1,
            mesAnio2: datosMesAnio2
        });
        setPorcentajeCambio(porcentaje);
    };

    // Crear gráfico
    useEffect(() => {
        if (modoComparativa === 'anual' && datosComparativa?.datosPorMes && chartRef.current) {
            if (chartInstance.current) {
                chartInstance.current.destroy();
            }

            const ctx = chartRef.current.getContext('2d');
            chartInstance.current = new Chart(ctx, {
                type: 'bar',
                data: {
                    labels: datosComparativa.datosPorMes.map(d => d.nombre),
                    datasets: [
                        {
                            label: `${anio1}`,
                            data: datosComparativa.datosPorMes.map(d => d.anio1),
                            backgroundColor: 'rgba(54, 162, 235, 0.7)',
                            borderColor: 'rgb(54, 162, 235)',
                            borderWidth: 2,
                            borderRadius: 5
                        },
                        {
                            label: `${anio2}`,
                            data: datosComparativa.datosPorMes.map(d => d.anio2),
                            backgroundColor: 'rgba(255, 99, 132, 0.7)',
                            borderColor: 'rgb(255, 99, 132)',
                            borderWidth: 2,
                            borderRadius: 5
                        }
                    ]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: {
                        legend: {
                            position: 'top',
                        },
                        tooltip: {
                            callbacks: {
                                label: function (context) {
                                    let label = context.dataset.label || '';
                                    if (label) label += ': ';
                                    label += `$${context.raw.toLocaleString()}`;
                                    return label;
                                }
                            }
                        }
                    },
                    scales: {
                        y: {
                            beginAtZero: true,
                            ticks: {
                                callback: function (value) {
                                    return `$${value.toLocaleString()}`;
                                }
                            }
                        }
                    }
                }
            });
        }

        return () => {
            if (chartInstance.current) {
                chartInstance.current.destroy();
            }
        };
    }, [modoComparativa, datosComparativa, anio1, anio2]);

    useEffect(() => {
        if (modoComparativa === 'anual') {
            calcularComparativaAnual();
        } else {
            calcularComparativaMensual();
        }
    }, [tipoComparativa, anio1, anio2, mesSeleccionado, modoComparativa, gananciasPorMesCompleto]);

    const esPositivo = porcentajeCambio >= 0;

    if (añosDisponibles.length === 0) {
        return (
            <Paper sx={{ p: 3, mb: 3 }}>
                <Typography textAlign="center" color="textSecondary">
                    No hay datos suficientes para mostrar comparativas
                </Typography>
            </Paper>
        );
    }

    return (
        <Paper sx={{ p: 3, mb: 3 }}>
            <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                <CompareArrows /> Comparativa Anual
            </Typography>

            <Grid container spacing={2} sx={{ mb: 3 }}>
                <Grid item xs={12} sm={6}>
                    <ToggleButtonGroup
                        value={modoComparativa}
                        exclusive
                        onChange={(e, val) => val && setModoComparativa(val)}
                        fullWidth
                        size="small"
                    >
                        <ToggleButton value="anual">
                            <BarChartIcon sx={{ mr: 1 }} /> Año vs Año
                        </ToggleButton>
                        <ToggleButton value="mensual">
                            <CalendarToday sx={{ mr: 1 }} /> Mes específico
                        </ToggleButton>
                    </ToggleButtonGroup>
                </Grid>

                <Grid item xs={12} sm={6}>
                    <ToggleButtonGroup
                        value={tipoComparativa}
                        exclusive
                        onChange={(e, val) => val && setTipoComparativa(val)}
                        fullWidth
                        size="small"
                    >
                        <ToggleButton value="ganancias">💰 Ganancias</ToggleButton>
                    </ToggleButtonGroup>
                </Grid>
            </Grid>

            <Grid container spacing={2}>
                <Grid item xs={12} sm={modoComparativa === 'anual' ? 6 : 12}>
                    <FormControl fullWidth size="small">
                        <InputLabel>Año {modoComparativa === 'anual' ? '1' : 'actual'}</InputLabel>
                        <Select value={anio1} onChange={(e) => setAnio1(e.target.value)} label={`Año ${modoComparativa === 'anual' ? '1' : 'actual'}`}>
                            {añosDisponibles.map(anio => (
                                <MenuItem key={anio} value={anio}>{anio}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                <Grid item xs={12} sm={modoComparativa === 'anual' ? 6 : 12}>
                    <FormControl fullWidth size="small">
                        <InputLabel>Año {modoComparativa === 'anual' ? '2' : 'anterior'}</InputLabel>
                        <Select value={anio2} onChange={(e) => setAnio2(e.target.value)} label={`Año ${modoComparativa === 'anual' ? '2' : 'anterior'}`}>
                            {añosDisponibles.map(anio => (
                                <MenuItem key={anio} value={anio}>{anio}</MenuItem>
                            ))}
                        </Select>
                    </FormControl>
                </Grid>

                {modoComparativa === 'mensual' && (
                    <Grid item xs={12}>
                        <FormControl fullWidth size="small">
                            <InputLabel>Mes</InputLabel>
                            <Select value={mesSeleccionado} onChange={(e) => setMesSeleccionado(e.target.value)} label="Mes">
                                {meses.map((mes, idx) => (
                                    <MenuItem key={idx} value={idx}>{mes}</MenuItem>
                                ))}
                            </Select>
                        </FormControl>
                    </Grid>
                )}
            </Grid>

            {datosComparativa && (
                <Box sx={{ mt: 3 }}>
                    <Card sx={{ mb: 3, bgcolor: esPositivo ? '#e8f5e9' : '#ffebee' }}>
                        <CardContent>
                            <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap' }}>
                                <Box>
                                    <Typography variant="body2" color="textSecondary">
                                        {modoComparativa === 'anual' ? 'Comparativa Anual' : `Comparativa ${datosComparativa.mes}`}
                                    </Typography>
                                    <Typography variant="h4" fontWeight="bold" color={esPositivo ? '#2e7d32' : '#c62828'}>
                                        {esPositivo ? <TrendingUp sx={{ fontSize: 30, verticalAlign: 'middle' }} /> : <TrendingDown sx={{ fontSize: 30, verticalAlign: 'middle' }} />}
                                        {Math.abs(porcentajeCambio).toFixed(1)}%
                                    </Typography>
                                    <Typography variant="body2">
                                        Diferencia: {esPositivo ? '+' : '-'}${Math.abs(datosComparativa.diferencia).toLocaleString()}
                                    </Typography>
                                </Box>

                                <Box sx={{ textAlign: 'right' }}>
                                    <Typography variant="h6" color="primary">
                                        {anio1}: ${datosComparativa.totalAnio1.toLocaleString()}
                                    </Typography>
                                    <Typography variant="body2" color="textSecondary">
                                        {anio2}: ${datosComparativa.totalAnio2.toLocaleString()}
                                    </Typography>
                                </Box>
                            </Box>
                        </CardContent>
                    </Card>

                    {modoComparativa === 'anual' && datosComparativa.datosPorMes && (
                        <>
                            <Box sx={{ height: 400, mb: 3 }}>
                                <canvas ref={chartRef} />
                            </Box>

                            <Typography variant="subtitle1" gutterBottom sx={{ mt: 2 }}>
                                Detalle por mes
                            </Typography>
                            <TableContainer component={Paper} sx={{ maxHeight: 400 }}>
                                <Table stickyHeader size="small">
                                    <TableHead>
                                        <TableRow sx={{ backgroundColor: '#f5f5f5' }}>
                                            <TableCell><strong>Mes</strong></TableCell>
                                            <TableCell align="right"><strong>{anio1}</strong></TableCell>
                                            <TableCell align="right"><strong>{anio2}</strong></TableCell>
                                            <TableCell align="right"><strong>Diferencia</strong></TableCell>
                                            <TableCell align="right"><strong>Variación</strong></TableCell>
                                        </TableRow>
                                    </TableHead>
                                    <TableBody>
                                        {datosComparativa.datosPorMes.map((mes) => {
                                            const variacion = mes.anio2 !== 0 ? ((mes.diferencia / mes.anio2) * 100) : (mes.anio1 > 0 ? 100 : 0);
                                            return (
                                                <TableRow key={mes.mes}>
                                                    <TableCell component="th" scope="row">{mes.nombre}</TableCell>
                                                    <TableCell align="right">${mes.anio1.toLocaleString()}</TableCell>
                                                    <TableCell align="right">${mes.anio2.toLocaleString()}</TableCell>
                                                    <TableCell align="right" sx={{ color: mes.diferencia >= 0 ? 'green' : 'red' }}>
                                                        {mes.diferencia >= 0 ? '+' : ''}${mes.diferencia.toLocaleString()}
                                                    </TableCell>
                                                    <TableCell align="right">
                                                        <Chip
                                                            size="small"
                                                            label={`${variacion >= 0 ? '+' : ''}${variacion.toFixed(1)}%`}
                                                            color={variacion >= 0 ? 'success' : 'error'}
                                                            variant="outlined"
                                                        />
                                                    </TableCell>
                                                </TableRow>
                                            );
                                        })}
                                    </TableBody>
                                </Table>
                            </TableContainer>
                        </>
                    )}

                    {modoComparativa === 'mensual' && (
                        <Grid container spacing={2} sx={{ mt: 1 }}>
                            <Grid item xs={12} sm={6}>
                                <Card sx={{ bgcolor: '#e3f2fd' }}>
                                    <CardContent>
                                        <Typography variant="subtitle2" color="primary">
                                            {meses[mesSeleccionado]} {anio1}
                                        </Typography>
                                        <Typography variant="h5" fontWeight="bold">
                                            ${datosComparativa.totalAnio1.toLocaleString()}
                                        </Typography>
                                        {datosComparativa.mesAnio1 && (
                                            <>
                                                <Typography variant="body2">
                                                    Días trabajados: {datosComparativa.mesAnio1.diasTrabajados?.size || 0}
                                                </Typography>
                                                <Typography variant="body2">
                                                    Promedio diario: ${Math.round(datosComparativa.totalAnio1 / (datosComparativa.mesAnio1.diasTrabajados?.size || 1)).toLocaleString()}
                                                </Typography>
                                            </>
                                        )}
                                    </CardContent>
                                </Card>
                            </Grid>

                            <Grid item xs={12} sm={6}>
                                <Card sx={{ bgcolor: '#fce4ec' }}>
                                    <CardContent>
                                        <Typography variant="subtitle2" color="secondary">
                                            {meses[mesSeleccionado]} {anio2}
                                        </Typography>
                                        <Typography variant="h5" fontWeight="bold">
                                            ${datosComparativa.totalAnio2.toLocaleString()}
                                        </Typography>
                                        {datosComparativa.mesAnio2 && (
                                            <>
                                                <Typography variant="body2">
                                                    Días trabajados: {datosComparativa.mesAnio2.diasTrabajados?.size || 0}
                                                </Typography>
                                                <Typography variant="body2">
                                                    Promedio diario: ${Math.round(datosComparativa.totalAnio2 / (datosComparativa.mesAnio2.diasTrabajados?.size || 1)).toLocaleString()}
                                                </Typography>
                                            </>
                                        )}
                                    </CardContent>
                                </Card>
                            </Grid>
                        </Grid>
                    )}
                </Box>
            )}
        </Paper>
    );
};

export default ComparativaAnual;